import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String engUzun = "";
        while (in.hasNext()) {
            String soz = in.next();
            if (soz.length() > engUzun.length()) engUzun = soz;
        }
        System.out.println(engUzun.isEmpty() ? "-" : engUzun);
    }
}

